import {
    isLikelyPublicStorageImageUrl,
    resolvePublicStorageUrl,
} from '@/features/selfServices/utils/resolvePublicStorageUrl';
import { cn } from '@/lib/utils';

type Props = {
    rawPath: string | null | undefined;
    className?: string;
    /** Larger thumbnail in detail modals */
    variant?: 'compact' | 'hero';
};

/** Filename segment for display when path is not image-previewable. */
function fileLabel(path: string): string {
    const seg = path.replace(/^.*[/\\]/, '').trim();
    return seg || 'مرفق';
}

export function SelfServiceAttachmentPreview({ rawPath, className, variant = 'compact' }: Props) {
    const url = resolvePublicStorageUrl(rawPath);
    if (!url) return null;

    const isImage = isLikelyPublicStorageImageUrl(url);

    if (isImage) {
        return (
            <div className={cn('rounded-xl overflow-hidden border border-[#E8E7EA] bg-[#F4F6FA]', className)}>
                <img
                    src={url}
                    alt=""
                    className={cn(
                        'w-full object-contain bg-black/[0.03]',
                        variant === 'hero' ? 'max-h-[min(52vh,420px)] min-h-[200px]' : 'max-h-48',
                    )}
                    loading="lazy"
                />
                <div className="flex items-center justify-between gap-2 px-3 py-2 bg-white/90 border-t border-[#E8E7EA]">
                    <span className="text-xs text-[#625E74] truncate">{fileLabel(rawPath ?? url)}</span>
                    <a
                        href={url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-xs font-semibold text-primery-blue-500 hover:underline shrink-0"
                    >
                        فتح في تبويب جديد
                    </a>
                </div>
            </div>
        );
    }

    return (
        <div
            className={cn(
                'flex flex-wrap items-center gap-3 rounded-xl border border-[#E8E7EA] bg-gradient-to-l from-white to-[#F8FAFC] px-4 py-3',
                className,
            )}
        >
            <div className="flex h-11 w-11 items-center justify-center rounded-lg bg-primery-blue-500/10 text-primery-blue-600">
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
                    <path
                        d="M14 2H6C5.46957 2 4.96086 2.21071 4.58579 2.58579C4.21071 2.96086 4 3.46957 4 4V20C4 20.5304 4.21071 21.0391 4.58579 21.4142C4.96086 21.7893 5.46957 22 6 22H18C18.5304 22 19.0391 21.7893 19.4142 21.4142C19.7893 21.0391 20 20.5304 20 20V8L14 2Z"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                    />
                    <path d="M14 2V8H20" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
            </div>
            <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-[#2D2D3A] truncate">{fileLabel(rawPath ?? url)}</p>
                <p className="text-xs text-[#90868C] mt-0.5">ملف مرفق</p>
            </div>
            <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center justify-center rounded-lg bg-primery-blue-500 px-3 py-2 text-xs font-semibold text-white hover:bg-primery-blue-600 transition-colors"
            >
                تنزيل / عرض
            </a>
        </div>
    );
}
