import { getResolvedApiBaseUrl } from '@/core/global-data/constants.data';

/** File extensions we treat as browser-displayable images for previews. */
const IMAGE_EXT = /\.(png|jpe?g|gif|webp|bmp|svg)$/i;

export function isLikelyPublicStorageImageUrl(url: string | null | undefined): boolean {
    if (!url || typeof url !== 'string') return false;
    const pathOnly = url.split('?')[0] ?? url;
    return IMAGE_EXT.test(pathOnly);
}

/** Fixes absolute URLs that wrongly expose `app/public` or nested `storage/app/public` instead of the web symlink `/storage/`. */
function rewriteAbsolutePublicUrl(url: string): string {
    try {
        const u = new URL(url);
        let path = u.pathname;
        path = path.replace(/\/storage\/app\/public\//gi, '/storage/');
        path = path.replace(/\/app\/public\//gi, '/storage/');
        // collapse accidental double storage segments
        path = path.replace(/\/storage\/storage\//g, '/storage/');
        u.pathname = path;
        return u.toString();
    } catch {
        return url;
    }
}

/**
 * Strips Laravel internal path prefixes so the public URL is always
 * `{origin}/storage/{relative}` (symlink to `storage/app/public`).
 */
function normalizeRelativePublicPath(raw: string): string {
    let p = raw.trim().replace(/^\/+/, '');
    // Repeatedly peel known prefixes until stable
    for (let i = 0; i < 8; i++) {
        const before = p;
        if (/^storage\/app\/public\//i.test(p)) p = p.replace(/^storage\/app\/public\//i, '');
        else if (/^storage\/app\//i.test(p)) p = p.replace(/^storage\/app\//i, '');
        else if (/^app\/public\//i.test(p)) p = p.replace(/^app\/public\//i, '');
        else if (/^public\/storage\//i.test(p)) p = p.replace(/^public\/storage\//i, '');
        else if (/^public\//i.test(p)) p = p.replace(/^public\//i, '');
        else if (/^storage\//i.test(p)) p = p.replace(/^storage\//i, '');
        if (p === before) break;
    }
    return p.replace(/^\/+/, '');
}

/** Builds absolute URL for a path stored under Laravel `storage/app/public` (or already absolute). */
export function resolvePublicStorageUrl(path: string | null | undefined): string | null {
    if (!path || typeof path !== 'string') {
        return null;
    }
    const trimmed = path.trim();
    if (!trimmed) {
        return null;
    }

    if (/^https?:\/\//i.test(trimmed)) {
        return rewriteAbsolutePublicUrl(trimmed);
    }

    const api = getResolvedApiBaseUrl();
    const origin = api.replace(/\/api\/?$/, '');
    const clean = normalizeRelativePublicPath(trimmed);

    if (!clean) {
        return null;
    }

    return `${origin}/storage/${clean}`;
}
